-- Name: User; Type: TABLE; Schema: public; Owner: chevron_user
--

CREATE TABLE public."User" (
    id text NOT NULL,
    name text NOT NULL,
    email text NOT NULL,
    password text NOT NULL,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "roleId" text NOT NULL,
    "employeeId" text,
    "resetOtp" text,
    "resetOtpExpireAt" timestamp(3) without time zone
);


ALTER TABLE public."User" OWNER TO chevron_user;

--
-- Name: WorkflowLog; Type: TABLE; Schema: public; Owner: chevron_user
--

CREATE TABLE public."WorkflowLog" (
    id text NOT NULL,
    "requestId" text NOT NULL,
    "userId" text,
    action text NOT NULL,
    comment text,
    "createdAt" timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


ALTER TABLE public."WorkflowLog" OWNER TO chevron_user;

--
-- Name: _prisma_migrations; Type: TABLE; Schema: public; Owner: chevron_user
--

CREATE TABLE public._prisma_migrations (
    id character varying(36) NOT NULL,
    checksum character varying(64) NOT NULL,
    finished_at timestamp with time zone,
    migration_name character varying(255) NOT NULL,
    logs text,
    rolled_back_at timestamp with time zone,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    applied_steps_count integer DEFAULT 0 NOT NULL
);


ALTER TABLE public._prisma_migrations OWNER TO chevron_user;

